Hmm, my suggestion function signature is confusing. Let me write something cleaner:

```js
/** bare 命令中 git <sub> 段是否带指定标志：短参支持合并（-Af），长参支持前缀（--forc） */
function gitSegmentHasFlag(bare, sub, shortChars, longPrefix) {
  return bare.split(/&&|\|\||;|\|/).some((seg) => {
    const tokens = seg.match(/\S+/g) ?? [];
    const gitIdx = tokens.findIndex((t, i) => t === "git" && tokens[i + 1] === sub);
    if (gitIdx === -1) return false;
    return tokens.slice(gitIdx + 2).some(
      (t) => t.startsWith(longPrefix) || (/^-\w+$/.test(t) && [...t.slice(1)].some((c) => shortChars.includes(c))),
    );
  });
}
```

And usage:
```js
const usesForce = gitSegmentHasFlag(bare, "add", "f", "--force");
const broadAdd = gitSegmentHasFlag(bare, "add", "Au", "--all");
```

